# The touched-step map: <path pattern> <step pattern>, using Bash patterns.
# ci-local.sh --tier touched reads it; ci-local.sh --check-map checks it.
# A path no line matches and no step names runs the full tier, so a gap fails safe.
# The gate's own files (this map, scripts/ci-local.sh, gate/lib.sh) always run the full tier.

# Rust: a change to a crate or the workspace runs every cargo step.
crates/*                    cargo *
Cargo.toml                  cargo *
Cargo.lock                  cargo *
rust-toolchain.toml         cargo *

# The gate library and the gate.
gate/*.sh                   shellcheck *
gate/*.sh                   bash tests/gate_vendor_test.sh
gate/*.sh                   bash tests/gate_lib_test.sh
gate/*.sh                   bash tests/ci_local_test.sh
gate/*.sh                   bash tests/gate_workflow_test.sh
gate/term-check.sh          bash tests/term_check_test.sh
gate/term-check.sh          bash tests/gate_scanners_test.sh
gate/secret-scan.sh         bash tests/secret_scan_test.sh
gate/secret-scan.sh         bash tests/gate_scanners_test.sh
gate/README.md              bash tests/gate_vendor_test.sh
gate/README.md              bash tests/gate_scanners_test.sh
gate/*.md                   -
gate/VERSION                -
scripts/*.sh                shellcheck *
scripts/ci-local.sh         bash tests/ci_local_test.sh
scripts/term-check.sh       bash tests/term_check_test.sh
scripts/secret-scan.sh      bash tests/secret_scan_test.sh
scripts/deps-check.sh       bash tests/deps_check_test.sh
tests/*.sh                  shellcheck *

# Prose and settings: the scanners, which every change runs, are enough.
README.md                   bash tests/gate_vendor_test.sh
*.md                        -
.ai/*.md                    -
LICENSE                     -
.gitignore                  -
